std::string decimal(Integer numerator, Integer denominator, int places) {
    Integer scale = 1;
    for (int i = 0; i < places; ++i) scale *= 10;
    Integer rounded = (2 * numerator * scale + denominator) / (2 * denominator);
    std::ostringstream stream;
    stream << rounded / scale << '.' << std::setw(places) << std::setfill('0') << rounded % scale;
    return stream.str();
}
Lines gridLines(const Grid& grid, const std::string& letters) { Lines lines; for (int row = 0; row < grid.height; ++row) lines.push_back(letters.substr(static_cast<std::size_t>(row * grid.width), grid.width)); return lines; }
Lines numberLines(const Layout& layout) {
    Lines lines;
    for (int row = 0; row < layout.grid.height; ++row) {
        Lines marks;
        for (int column = 0; column < layout.grid.width; ++column) {
            int cell = layout.grid.cell(row, column), number = layout.numbers[cell];
            marks.push_back(!layout.grid.isOpen(row, column) ? "##" : number ? (number < 10 ? " " : "") + text(number) : " .");
        }
        lines.push_back(join(marks));
    }
    return lines;
}
std::string listLine(const Slot& slot, const std::string& clue, const std::string& entry, const std::string& score, bool theme) { return text(slot.number, ". ", clue, " (", slot.length(), ") ", entry, ' ', score, theme ? " theme" : ""); }

#include "crossword.hpp"

bool startsRun(const Grid& grid, int row, int column, bool across) { return grid.isOpen(row, column) && !grid.isOpen(row - (across ? 0 : 1), column - (across ? 1 : 0)); }
int runLength(const Grid& grid, int row, int column, bool across) { int length = 0; while (grid.isOpen(row + (across ? 0 : length), column + (across ? length : 0))) ++length; return length; }
std::pair<int, std::string> findShortRun(const Grid& grid) {
    for (int row = 0; row < grid.height; ++row) for (int column = 0; column < grid.width; ++column) for (bool across : {true, false}) if (startsRun(grid, row, column, across) && runLength(grid, row, column, across) == 2) return {grid.cell(row, column), across ? "across" : "down"};
    return {-1, ""};
}
Layout::Layout(Grid grid) : grid(std::move(grid)), numbers(this->grid.cells.size()), acrossSlot(this->grid.cells.size(), -1), downSlot(this->grid.cells.size(), -1) {
    int next = 0;
    for (int row = 0; row < this->grid.height; ++row) for (int column = 0; column < this->grid.width; ++column) for (bool across : {true, false}) {
        if (!startsRun(this->grid, row, column, across)) continue;
        int length = runLength(this->grid, row, column, across);
        if (length < 3) continue;
        int start = this->grid.cell(row, column);
        if (!numbers[start]) numbers[start] = ++next;
        Slot slot{static_cast<int>(slots.size()), numbers[start], across, {}, {}, text(numbers[start], across ? 'A' : 'D')};
        for (int i = 0; i < length; ++i) { int position = this->grid.cell(row + (across ? 0 : i), column + (across ? i : 0)); slot.cells.push_back(position); (across ? acrossSlot : downSlot)[position] = slot.index; }
        slots.push_back(std::move(slot));
    }
    for (Slot& slot : slots) { for (int position : slot.cells) { int crossing = (slot.across ? downSlot : acrossSlot)[position]; if (crossing >= 0) slot.crossings.push_back(crossing); } std::sort(slot.crossings.begin(), slot.crossings.end()); }
}
int Layout::ownerCount(int cell) const { return static_cast<int>(acrossSlot[cell] >= 0) + static_cast<int>(downSlot[cell] >= 0); }
int Layout::orphanCell() const { for (int cell : grid.whites()) if (!ownerCount(cell)) return cell; return -1; }

#include "crossword.hpp"

bool validWord(const std::string& value) { if (value.size() < 3 || value.size() > 15) return false; return std::all_of(value.begin(), value.end(), [](char symbol) { return symbol >= 'A' && symbol <= 'Z'; }); }
bool validInteger(const std::string& value, int low, int high) {
    if (value.empty() || value.front() == '0' || value.size() > text(high).size()) return false;
    if (!std::all_of(value.begin(), value.end(), [](char symbol) { return symbol >= '0' && symbol <= '9'; })) return false;
    int integer = std::stoi(value);
    return integer >= low && integer <= high;
}
std::string wordLineError(const std::string& line) {
    if (std::count(line.begin(), line.end(), ' ') != 1) return "bad format";
    std::size_t space = line.find(' ');
    if (!validWord(line.substr(0, space))) return "bad word";
    return validInteger(line.substr(space + 1), 1, 100) ? "" : "bad score";
}
std::string clueLineError(const std::string& line) {
    if (std::count(line.begin(), line.end(), '|') != 1) return "bad format";
    std::size_t bar = line.find('|');
    if (!validWord(line.substr(0, bar))) return "bad word";
    std::string clue = line.substr(bar + 1);
    return clue.empty() || clue.size() > 60 || clue.front() == ' ' || clue.back() == ' ' ? "bad clue" : "";
}
bool matches(const std::string& word, const std::string& pattern) { if (word.size() != pattern.size()) return false; for (std::size_t i = 0; i < word.size(); ++i) if (pattern[i] != '.' && pattern[i] != word[i]) return false; return true; }
WordIndex::WordIndex(std::map<std::string, int> scores) : scores(std::move(scores)) {
    for (const std::pair<const std::string, int>& entry : this->scores) ranked.push_back(entry.first);
    std::sort(ranked.begin(), ranked.end(), [&](const std::string& a, const std::string& b) { return this->scores.at(a) != this->scores.at(b) ? this->scores.at(a) > this->scores.at(b) : a < b; });
    for (const std::string& word : ranked) { int length = static_cast<int>(word.size()); byLength[length].push_back(word); for (int position = 0; position < length; ++position) byLetter[{length, position, word[position]}].push_back(word); }
}
Lines WordIndex::candidates(const std::string& pattern, int minimum, const std::set<std::string>& used) const {
    int length = static_cast<int>(pattern.size());
    std::map<int, Lines>::const_iterator lengthEntry = byLength.find(length);
    if (lengthEntry == byLength.end()) return {};
    const Lines* pool = &lengthEntry->second;
    for (int position = 0; position < length; ++position) if (pattern[position] != '.') {
        std::map<std::tuple<int, int, char>, Lines>::const_iterator bucket = byLetter.find({length, position, pattern[position]});
        if (bucket == byLetter.end()) return {};
        if (bucket->second.size() < pool->size()) pool = &bucket->second;
    }
    Lines result;
    for (const std::string& word : *pool) { if (scores.at(word) < minimum) break; if (!used.count(word) && matches(word, pattern)) result.push_back(word); }
    return result;
}
